/**
 * Canonical JSON and domain-separated hashing, ported from
 * `sccp/serialization.py`.
 *
 * Every hash the protocol signs is
 * `sha256(utf8(domain) + 0x00 + canonical_json(payload))`, where canonical JSON
 * means: object keys sorted, no whitespace, NFC-normalized strings, integers
 * only. Getting this wrong produces signatures that `sccp verify` rejects, so
 * `canonical.test.ts` pins it against vectors generated by the Python module.
 */

import { sha256 } from "@noble/hashes/sha2.js";

export type Json = null | boolean | number | bigint | string | Json[] | { [key: string]: Json };

/** Hash domains from `sccp.serialization.Domain` (docs/PROTOCOL.md section 1). */
export const DOMAINS = {
  ADDRESS: "sccp/v1/address",
  BEACON: "sccp/v1/beacon",
  BEACON_COMMIT: "sccp/v1/beacon-commit",
  BLOCK: "sccp/v1/block",
  CERTIFICATE: "sccp/v1/certificate",
  CHALLENGE: "sccp/v1/challenge",
  CLOCK: "sccp/v1/clock",
  GAME: "sccp/v1/game",
  GOSSIP: "sccp/v1/gossip",
  HEADER: "sccp/v1/header",
  MATCH: "sccp/v1/match",
  MOVE: "sccp/v1/move",
  OPENING: "sccp/v1/opening",
  PAIR: "sccp/v1/pair",
  PROOF: "sccp/v1/proof",
  QUALITY: "sccp/v1/quality",
  RESULT: "sccp/v1/result",
  TX: "sccp/v1/tx",
} as const;

export type Domain = (typeof DOMAINS)[keyof typeof DOMAINS];

const REGISTERED: ReadonlySet<string> = new Set(Object.values(DOMAINS));

/** Integers outside this range are refused (``INT_MIN``/``INT_MAX`` in Python). */
export const INT_MIN = -(2n ** 63n);
export const INT_MAX = 2n ** 64n - 1n;

export class CanonicalJsonError extends Error {
  override name = "CanonicalJsonError";
}

/**
 * Convert a value to canonical JSON form, coercing nothing.
 *
 * Mirrors `sccp.serialization.normalize`: floats, `undefined`, functions and
 * symbols are refused rather than coerced, because a value with no canonical
 * encoding must never be signed. `bigint` is accepted (JavaScript's only exact
 * integer type above 2^53) and encoded as a decimal literal; plain `number` is
 * limited to the safe integer range, so a value that lost precision in
 * `JSON.parse` is rejected instead of silently hashed wrong.
 */
export function normalize(value: unknown): Json {
  if (value === null) return null;
  if (typeof value === "boolean") return value;
  if (typeof value === "bigint") {
    if (value < INT_MIN || value > INT_MAX) {
      throw new CanonicalJsonError(`integer ${value} outside [INT_MIN, INT_MAX]`);
    }
    return value;
  }
  if (typeof value === "number") {
    if (!Number.isInteger(value)) {
      throw new CanonicalJsonError(`canonical JSON has no floats: ${value}`);
    }
    if (!Number.isSafeInteger(value)) {
      throw new CanonicalJsonError(`integer ${value} is outside the safe range`);
    }
    return value;
  }
  if (typeof value === "string") return value.normalize("NFC");
  if (Array.isArray(value)) return value.map((item) => normalize(item));
  if (typeof value === "object") {
    const prototype = Object.getPrototypeOf(value) as object | null;
    if (prototype !== Object.prototype && prototype !== null) {
      // Uint8Array, Map, Date and class instances have no canonical encoding.
      const name = (value as { constructor?: { name?: string } }).constructor?.name ?? "object";
      throw new CanonicalJsonError(`unsupported canonical JSON type: ${name}`);
    }
    const out: { [key: string]: Json } = {};
    for (const [rawKey, item] of Object.entries(value as Record<string, unknown>)) {
      if (item === undefined) {
        throw new CanonicalJsonError(`object key ${rawKey} has no value`);
      }
      const key = rawKey.normalize("NFC");
      if (Object.prototype.hasOwnProperty.call(out, key)) {
        throw new CanonicalJsonError(`duplicate object key after NFC: ${key}`);
      }
      out[key] = normalize(item);
    }
    return out;
  }
  throw new CanonicalJsonError(`unsupported canonical JSON type: ${typeof value}`);
}

/**
 * Compare two strings by Unicode code point, which is how Python's
 * `sorted()` orders `str`. `Array.prototype.sort` compares UTF-16 code units,
 * so it misorders astral characters against U+E000..U+FFFF.
 */
export function compareCodePoints(a: string, b: string): number {
  const left = a[Symbol.iterator]();
  const right = b[Symbol.iterator]();
  for (;;) {
    const x = left.next();
    const y = right.next();
    if (x.done === true && y.done === true) return 0;
    if (x.done === true) return -1;
    if (y.done === true) return 1;
    const cx = x.value.codePointAt(0) ?? 0;
    const cy = y.value.codePointAt(0) ?? 0;
    if (cx !== cy) return cx - cy;
  }
}

function encode(value: Json): string {
  if (value === null) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "number") return String(value); // integers only by now
  if (typeof value === "string") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map((item) => encode(item)).join(",")}]`;
  const keys = Object.keys(value).sort(compareCodePoints);
  const members = keys.map((key) => `${JSON.stringify(key)}:${encode(value[key] as Json)}`);
  return `{${members.join(",")}}`;
}

/** Encode `value` as canonical UTF-8 JSON (sorted keys, no whitespace). */
export function canonicalJson(value: unknown): string {
  return encode(normalize(value));
}

/** ``sha256(domain + 0x00 + canonical_json(payload))`` as raw bytes. */
export function domainHash(domain: Domain | string, payload: unknown): Uint8Array {
  if (!REGISTERED.has(domain)) {
    throw new CanonicalJsonError(`unknown hash domain: ${domain}`);
  }
  const prefix = new TextEncoder().encode(`${domain}\u0000`);
  const body = new TextEncoder().encode(canonicalJson(payload));
  const message = new Uint8Array(prefix.length + body.length);
  message.set(prefix, 0);
  message.set(body, prefix.length);
  return sha256(message);
}

/** Lowercase hex form of {@link domainHash}. */
export function domainHex(domain: Domain | string, payload: unknown): string {
  return toHex(domainHash(domain, payload));
}

export function toHex(bytes: Uint8Array): string {
  let out = "";
  for (const byte of bytes) out += byte.toString(16).padStart(2, "0");
  return out;
}

export function fromHex(text: string): Uint8Array {
  if (text.length % 2 !== 0 || /[^0-9a-fA-F]/.test(text)) {
    throw new CanonicalJsonError(`not lowercase/uppercase hex: ${text}`);
  }
  const out = new Uint8Array(text.length / 2);
  for (let index = 0; index < out.length; index += 1) {
    out[index] = Number.parseInt(text.slice(index * 2, index * 2 + 2), 16);
  }
  return out;
}
